INSERT INTO shell_identity_entries (entry_id, shell_id, kind, entry_date, source_tag, body, created_at, retired_at, is_deleted) VALUES (7, 3, 'lns', '2026-06-24', 'memory-durability', './sc mem writes land in the LIVE engine DB (.super-coder/shell_db.db) — gitignored and rebuilt from .sc-state/content.sql. They are session-durable but NOT rebuild-durable until snapshotted to content.sql, which is an admin/GUI step I can''t run as a normal shell (SC_ADMIN=1 ./sc snapshot, or GUI Snapshot button). So: (1) for anything that must survive long-term, also anchor it in a git-tracked file (e.g. a repo README) — the repo map surfaces those on every orientation, no snapshot needed; (2) after writing important memory, tell the FnB to Snapshot. Verify durability with: grep -c ''<title>'' .sc-state/content.sql — 0 means live-only.', '2026-06-24 11:27:26', NULL, 0);
INSERT INTO shell_identity_entries (entry_id, shell_id, kind, entry_date, source_tag, body, created_at, retired_at, is_deleted) VALUES (8, 3, 'lns', '2026-07-02', NULL, 'Driving the Windows Test VM from the sandbox: (1) always exec via powershell -EncodedCommand (base64 UTF-16LE) - inline quoting dies over ssh; (2) never emit non-ASCII from the guest - the broker /exec crashes on non-UTF-8 stdout (super-coder#261); base64 file content guest-side; (3) beyond that, backslash-doublequote inside PS double-quoted strings silently truncates - build paths with Join-Path/variables; (4) GUI needs the console session: schtasks /create /it + /run executes in session 1 (rst_uia.ps1 driver on Z:); ssh-spawned GUI apps are invisible; (5) capture returns screenshot_b64; (6) Revit needs Autodesk sign-in - no cached session in snapshot means no in-Revit testing (QAQC-2).', '2026-07-02 22:07:42', NULL, 0);
INSERT INTO shell_identity_entries (entry_id, shell_id, kind, entry_date, source_tag, body, created_at, retired_at, is_deleted) VALUES (9, 3, 'lns', '2026-07-03', NULL, 'Windows testing: OpenSSH sessions for admin users carry the FULL elevated token, interactive GUI apps run the filtered one - so a filesystem/registry test that passes over the broker exec loop can fail in the real app with UnauthorizedAccessException (caught rst-c flag#15 exactly this way). Verify permission-sensitive behavior in-session (schtasks /it or UIA-driven), not just over ssh. Also: WebView2 UIA trees are empty until a UIA client interacts once (click into the window, re-query); WPF ribbon panel CONTENTS are UIA-invisible - use AutomationElement.FromPoint + tree-derived coords with screenshot verify.', '2026-07-03 06:29:35', NULL, 0);
INSERT INTO shell_identity_entries (entry_id, shell_id, kind, entry_date, source_tag, body, created_at, retired_at, is_deleted) VALUES (10, 3, 'lns', '2026-07-18', NULL, 'Building .NET in the sandbox: no system dotnet — install with ''curl -sSL https://dot.net/v1/dotnet-install.sh | bash -s -- --channel 8.0 --install-dir ~/.dotnet'' and export PATH=$HOME/.dotnet:$PATH DOTNET_SYSTEM_GLOBALIZATION_INVARIANT=1 (no libicu in container — dotnet core-dumps without the flag). File-locking on Linux CI: .NET only enforces FileShare via advisory locks — a write-access open with FileShare.Read DOES hold a lock that a FileShare.None open conflicts with, but a (Write, Share.ReadWrite) probe takes no lock and sails through; read-only opens never lock. When lock semantics matter cross-platform, don''t reason from Windows sharing rules — run the actual open matrix in a scratch console app first (10 min, caught 4 test failures here).', '2026-07-18 18:38:08', NULL, 0);

DELETE FROM shell_decisions;
INSERT INTO shell_decisions (decision_id, shell_id, decision_date, priority, decision, rationale, parent_decision_id, is_deleted, created_at, feature_id, document_id) VALUES (1, 5, '2026-06-29', 'M', 'Assembly isolation: R27-forward. Per FnB (2026-06-29), R25/R26 keep the shared AssemblyLoadContext.Default load in RstBootstrap (cross-addin WebView2/STJ/Serilog contamination accepted as low-likelihood); rely on Revit 2027''s built-in per-addin ALC isolation. No private-ALC change shipped.', NULL, NULL, 0, '2026-06-29 18:09:47', NULL, NULL);
INSERT INTO shell_decisions (decision_id, shell_id, decision_date, priority, decision, rationale, parent_decision_id, is_deleted, created_at, feature_id, document_id) VALUES (2, 1, '2026-07-18', 'M', 'Telemetry v1 local store: JSONL append-only outbox under %LOCALAPPDATA%\RST\telemetry\, not SQLite. Native SQLite (e_sqlite3) risks version collisions in the shared AssemblyLoadContext.Default on Revit 2025/2026 (see decision #1); JSONL matches the app''s JSON idiom, is crash-safe (partial trailing line only), and volume (~tens of MB/quarter) lets the in-Revit dashboard aggregate on demand. LOCALAPPDATA (not the Roaming %AppData%\RST root) because telemetry is machine-scoped — roaming profiles must not merge outboxes across machines. Local retention (default 180 days) is independent of any future server ack — delete-on-confirm must never erase the user''s own dashboard history. Revisit only if local write patterns need update-in-place.', NULL, NULL, 0, '2026-07-18 10:10:43', NULL, NULL);
INSERT INTO shell_decisions (decision_id, shell_id, decision_date, priority, decision, rationale, parent_decision_id, is_deleted, created_at, feature_id, document_id) VALUES (3, 1, '2026-07-18', 'M', 'SC-032 ruling: WorksharingCentralGUID is Revit Server-only (Autodesk-documented), so spec 5''s current-file matching gains normalized central_path between central GUID and creation_guid — cloud pair → central GUID → central_path (case-insensitive ordinal) → creation_guid. Capture unchanged (raw, null-on-failure); presentation matching and HealthContext keys updated. Rationale: central_path is already captured, matches the research doc''s server resolution priority (central GUID/path), and prevents file-share centrals merging lineage siblings via creation-GUID fallback.', NULL, NULL, 0, '2026-07-18 20:38:13', NULL, NULL);

