INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (1, 'blocked-on-md-converter-video', 'Medium', 'Docs work paused pending md-converter inline video support (another shell adding it; host must shut down + update to pick it up). Resume feature #1 once video lands; then settle README strategy + granularity.', '2026-06-24', '2026-06-24', 1, 1, 1, 'md-converter now renders bare video URLs as players — github.com/user-attachments/assets/<id> or any .mp4/.webm/.mov/.ogg URL on its own line. Video question answered. Proceeding with docs work.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (2, 'import-id-path-traversal', 'High', 'ProfileZip.Install uses unsanitized profile.Id from imported zip as a filesystem path (Path.Combine(appDataRoot, Id)) — VM-verified arbitrary file write outside %AppData%\RST. Sanitize Id to GUID-shape on import. ProfileZip.cs:145-148; import at LoaderBridge.cs:321.', '2026-06-29', '2026-06-29', 1, 5, NULL, 'Fixed in PR #74 — GUID-coerce profile.Id + path confinement on import; VM-reproduced then fixed. Pending FnB merge.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (3, 'url-slot-shellexec-rce', 'High', 'UrlNormalizer passes file:// and ftp:// through unchanged into Process.Start(UseShellExecute=true) (SlotInvokeCommand.cs:47). VM-verified: a shared profile button can shell-execute an arbitrary local/UNC .exe on click. Needs scheme allowlist. UrlNormalizer.cs:24-43.', '2026-06-29', '2026-06-29', 1, 5, NULL, 'Fixed in PR #74 — UrlNormalizer.TryGetLaunchTarget scheme allowlist (http/https/mailto/tel) at both launch sites; VM-reproduced then fixed.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (4, 'health-clean-no-confinement', 'High', 'HealthCleaner.PurgeFlat recursively deletes a profile-supplied cleanup target Path with NO allowlist/root-confinement (CleanupPathResolver does no validation; BanList is only a command-id filter). An imported profile can point a directory target at C:\, a UNC share, or the user docs and wipe it. HealthCleaner.cs:108; CleanupPathResolver.cs.', '2026-06-29', '2026-06-29', 1, 5, NULL, 'Fixed in PR #75 — HealthCleaner/MeasureCleanup locked to CleanupDefaults preset paths; custom paths removed from Builder.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (5, 'loader-xss-bridge-takeover', 'High', 'Loader escHtml (profile_loader.html:963) does not escape quotes and is used inside href/title attributes with profile-supplied addin URLs (1335,1490); stack tool name rendered unescaped (1188). Stored XSS from a shared profile escalates via the pywebview shim to full bridge control (delete/apply/rename .addin). No CSP on any page.', '2026-06-29', '2026-06-29', 1, 5, NULL, 'Fixed in PR #80 — quote-safe escHtml + escaped stack tool name; CSP added (font origins allowlisted). Needs in-Revit smoke test of WebView2 render.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (6, 'required-addin-policy-mismatch', 'High', 'Three match policies disagree: RequiredAddinQa.FindMatch is 3-tier (incl fuzzy/tab) but AddinDisabler.IsRequired/RestoreRequired are 2-tier. DisableNonRequired disables a profile''s OWN tier-3-matched required add-in; RestoreRequired fails to restore it while the UI reports success. Reproducible with docs'' Lumion example. AddinDisabler.cs:75,115-123,189-202 vs RequiredAddinQa.cs:124-170.', '2026-06-29', '2026-06-29', 1, 5, NULL, 'Fixed in PR #77 — IsRequired/RestoreRequired now share RequiredAddinQa 3-tier matcher; tier-3 restore regression test added.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (7, 'save-filename-collision-dataloss', 'High', 'ProfileStore.Save keys the filename on ProfileName+date (not Id) and Resolve falls back to name match; a same-named different-Id profile is silently overwritten or deleted on save/import. Data loss, no warning. ProfileStore.cs:85-97,109-116.', '2026-06-29', '2026-06-29', 1, 5, NULL, 'Fixed in PR #76 — filename keyed on Id (no same-name clobber); regression test added.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (8, 'no-assembly-isolation', 'Medium', 'Bootstrap loads engine + transitives into AssemblyLoadContext.Default and attaches a process-global Resolving handler never removed — diamond-dependency clashes (WebView2/STJ/Serilog) with other add-ins and contaminates their resolution. RstBootstrap.cs:60-77.', '2026-06-29', '2026-06-29', 1, 5, NULL, 'Won''t-fix per FnB (2026-06-29): R25/R26 stay on shared Default ALC; rely on Revit 2027''s built-in per-addin ALC isolation going forward.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (9, 'cleaner-follows-symlinks', 'Medium', 'EnumerateFilesSafe/MeasureDirectory walk reparse points with no FileAttributes.ReparsePoint check; a junction/symlink under Temp (common) causes deletion of the link target''s real files outside the intended tree. HealthCleaner.cs:262-265; HealthScanner.cs:176-179.', '2026-06-29', '2026-06-29', 1, 5, NULL, 'Fixed in PR #75 — reparse-point (junction/symlink) dirs skipped in both cleaner walk and size preview.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (10, 'non-atomic-writes-dataloss', 'Medium', 'ProfileStore.Save (delete-then-File.Create) and PurgeRecentFileList (delete-then-Move on Revit.ini) are non-atomic; a crash in the window loses the profile / the entire Revit.ini. Use temp+File.Replace. ProfileStore.cs:88-95; HealthCleaner.cs:214-215.', '2026-06-29', '2026-06-29', 1, 5, NULL, 'Fixed in PR #75 (Revit.ini File.Replace) + PR #76 (ProfileStore temp+swap) — atomic writes.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (11, 'rstify-soft-lockout', 'Medium', 'RstifyToggle.SetVisibility hides any tab whose title is in the profile''s hidden_tabs with no exclusion for the Add-Ins host tab — hiding ''Add-Ins'' hides the only UI to switch profiles / toggle RSTify back. Docs claim the rst-c tab is never hidden; no code enforces it. Confirm intended vs gap. RstifyToggle.cs:193-216.', '2026-06-29', '2026-06-29', 1, 5, NULL, 'Fixed in PR #78 — RstifyToggle.SetVisibility never hides the Add-Ins host tab (found by the RST panel) or RST-managed tabs.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (12, 'msi-version-not-threaded', 'Medium', 'MSI Version is hardcoded 1.2.0 in both Product.wxs and not threaded from the release tag; a forgotten bump means ProductVersion doesn''t increase, MajorUpgrade/RemoveExistingProducts don''t run, and in-place upgrades silently fail (stale engine retained). installer/Product.wxs:44, installer-r27/Product.wxs:33, release.yml.', '2026-06-29', '2026-06-29', 1, 5, NULL, 'Fixed in PR #79 — MSI ProductVersion threaded from the release tag via _build.yml/release.yml; WiX var resolution VM-verified.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (13, 'QAQC-1', 'High', 'QAQC follow-through — merge PRs #88/#89/#90 (all CI-green), then run the VM manual test pass from doc #3 (broker up). Priority checks: #88 RST.addin survives disable-unused + modal shows RST staying; #89 blank-panel-name save rejected visibly + corrupt-zip import shows error dialog. Remaining med/low QAQC findings stay in doc #3 for triage.', '2026-07-02', '2026-07-02', 1, 3, NULL, 'PRs #88/#89/#90 merged (8456c0b). VM pass run 2026-07-02, results in doc #4: installers PASS (upgrade/side-by-side/uninstall-preserves-data; same-version collision CONFIRMED as known High 8), #88 self-protection + #89 validation verified at core level on the real box (85 real manifests, disable/restore roundtrip clean; 140+7 tests green on VM). In-Revit GUI half blocked by Autodesk sign-in wall -> QAQC-2 (operator: sign in + re-snapshot). Med/low findings stay in doc #3 for triage.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (14, 'QAQC-2', 'High', '[QAQC] In-Revit GUI testing blocked: Revit 2026 on W10C_DOS-ARCH_Testing demands Autodesk sign-in (no cached session in clean snapshot); only the operator can sign in + re-snapshot | Blocker for: QAQC-1 manual test pass (in-Revit half: disable-unused modal, import dialogs, ribbon/health/appearance sweep)', '2026-07-02', '2026-07-03', 1, 3, NULL, 'Cleared 2026-07-03: operator signed in on VM console (jedBPKK4); in-Revit GUI half of doc #3 checklist executed same day — results + 2 new bugs in doc #4 addendum. Residual ask moved there: re-snapshot ''clean'' WITH the cached sign-in (and fix windows-mcp task port 8000 collision) or every reset re-locks this.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (15, 'Disable-unused silently fails under non-elevated Revit (UI claims success)', 'High', 'Confirm modal lists ProgramData manifests under WILL BE DISABLED, but every rename throws UnauthorizedAccessException (interactive Revit = filtered token; the earlier core-harness pass passed only because OpenSSH carries the elevated admin token). failed_disables:5 reaches the UI layer and is discarded - no toast/dialog, QA reports all-clear, loader auto-closes. Fix: writability probe must probe as the running token, and failed disables must surface in the GUI. Secondary: RSTify hidden tabs reset on first doc-open after restart (Medium, see doc #4 addendum). Evidence: doc #4 addendum 2026-07-03, VM log rst_2026-07-03 08:11:53.', '2026-07-03', NULL, 0, 3, NULL, NULL, NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (16, 'SC-016', 'High', '[Review] TelemetryPrefs still fails open for damaged existing state: File.Exists returns false on permission/IO errors so unreadable is misclassified as first-run missing, and valid-but-incomplete objects such as {} or missing enabled deserialize to Enabled=true | Blocker for: telemetry v1 unit 1', '2026-07-18', '2026-07-18', 1, 5, 2, 'Resolved by PR #100 @ 485abb4: Read opens directly; only FileNotFoundException/DirectoryNotFoundException yield first-run enabled defaults. All other read failures fail closed, and nullable read DTO requires an explicit boolean enabled. Regression covers directory-at-path plus missing/null enabled.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (17, 'SC-017', 'Medium', '[Review] RetentionPruner accepts unbounded positive retentionDays and calls utcNow.AddDays outside its catch; a corrupt large value throws despite the never-throws contract | Blocker for: telemetry v1 unit 1', '2026-07-18', '2026-07-18', 1, 5, 2, 'Resolved at c35ff62: retentionDays is rejected when <=0 or >3650 before AddDays; Max+1 and int.MaxValue negative tests guard the reported overflow path.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (18, 'SC-018', 'Medium', '[Review] InstallIdStore first-run creation is a check-then-overwrite race: simultaneous Revit instances can return different install IDs for the same machine; no concurrent test guards the explicit multi-instance edge | Blocker for: telemetry v1 unit 1', '2026-07-18', '2026-07-18', 1, 5, 2, 'Resolved for the reported fresh-install race at c35ff62: FileMode.CreateNew atomically claims a missing install_id and losers re-read the winner; 8-thread first-run test covers it. Distinct corrupt-file repair race tracked as SC-022.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (19, 'SC-019', 'Medium', '[Review] TelemetryJson still accepts an incomplete/invalid mandatory envelope: absent schema_version/source are silently synthesized by property initializers, and non-GUID or whitespace event_id/session_guid pass; such a session_end can still satisfy closed-state and be pruned | Blocker for: telemetry v1 unit 1', '2026-07-18', '2026-07-18', 1, 5, 2, 'Resolved by PR #100 @ 485abb4: TryParseLine validates raw mandatory-key presence before deserialization and enforces GUID identities, seq>=1, parseable ts, nonblank event_type, schema_version=1, source addin|recovery. Parser, recovery, and prune negatives cover the closed-file consequence.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (20, 'SC-020', 'Medium', '[Review] OutboxWriter invokes the injected logger synchronously under the queue lock from Enqueue; unit 2''s ratified Serilog wiring would put logging IO/blocking back on the Revit event thread, violating capture-plus-enqueue-only | Blocker for: telemetry v1 unit 1', '2026-07-18', '2026-07-18', 1, 5, 2, 'Resolved at c35ff62: Enqueue only sets a pending warning under the queue lock; the writer thread emits the one-shot log, and the regression test asserts no synchronous logger call.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (21, 'SC-021', 'Medium', '[Review] Recovery tests do not cover the ratified Failed and missing/other doc_closed status branches; a realistic regression to Cancelled-only or null-means-open passes the suite | Blocker for: telemetry v1 unit 1', '2026-07-18', '2026-07-18', 1, 5, 2, 'Resolved at c35ff62: exact recovery cases now cover Cancelled and Failed as open, and missing/other status as closed, matching the ratified sprint judgement.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (22, 'SC-022', 'Medium', '[Review] Concurrent repair of an existing corrupt install_id uses unchecked File.WriteAllText last-writer-wins; two instances can each return a different minted ID while only the last persists. Repair must re-read/serialize under an exclusive claim and have a corrupt-file concurrency regression | Blocker for: telemetry v1 unit 1', '2026-07-18', '2026-07-18', 1, 5, 2, 'Resolved by PR #100 @ 485abb4: corrupt install_id repair uses an exclusive ReadWrite/FileShare.None handle; competing repairers retry and re-read the persisted winner under lock. Eight-thread regression asserts every return equals the on-disk id and would fail the prior last-writer-wins repair.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (23, 'SC-023', 'Medium', '[Review round 2] Cloud identity is not treated as an atomic project+model pair: BuildMatcher accepts a matching cloud_model_guid when cloud_project_guid is absent, before checking a conflicting lower creation key; partial capture can therefore attribute another model''s events to the current file | Blocker for: Sprint 6 unit 3 / PR #101', '2026-07-18', '2026-07-18', 1, 5, 2, 'Fixed at PR #101 commit c1f8b33: cloud matching now confirms only a complete matching project+model pair, rejects either present conflicting half, and falls through on incomplete pairs so central/creation keys decide; negative regression test proves matching model + missing project + conflicting creation yields zero attribution. Six CI checks green.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (24, 'SC-024', 'Medium', '[Review] An unmatched or failed doc_opening remains pending, and the recency fallback can pair it to a later unrelated doc_opened, inventing a load-duration point | Blocker for: Sprint 6 unit 3 / PR #101', '2026-07-18', '2026-07-18', 1, 5, 2, 'Resolved at a8e9376: doc_opened fallback only consumes a pending doc_opening when paths match or at least one side lacks a path; the new conflicting-nonblank-path regression test asserts both no invented load point and preserved open interval.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (25, 'SC-025', 'Medium', '[Review] doc_saved_as is ignored: when Save As changes the current file''s cloud/central identity, the original doc_opened no longer matches and no interval begins for the new identity, so post-save open hours disappear | Blocker for: Sprint 6 unit 3 / PR #101', '2026-07-18', '2026-07-18', 1, 5, 2, 'Resolved at a8e9376: doc_saved_as ends the old keyed interval and begins the new keyed interval at the Save As timestamp via previous_local_path; mirror and join-key-continuity tests cover both identities and the ratified old-identity cutoff.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (26, 'SC-026', 'High', '[Review] IdentityCapture.CaptureFull calls BasicFileInfo.Extract for every nonempty PathName, including UNC/network-hosted models, so doc-open/save handlers can block on network IO despite the explicit local-header-only rule | Blocker for: Sprint 6 unit 2 / PR #102', '2026-07-18', '2026-07-18', 1, 5, 2, 'Fixed at PR #102 commit 5bd4c1d: CaptureFull calls BasicFileInfo only after LocalPathGuard proves a rooted drive-letter path is on a local DriveType; UNC, cloud, mapped network, and probe failure fail closed; regression tests cover classification.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (27, 'SC-027', 'Medium', '[Review] IdentityCapture.TrackingKey uses mutable PathName/Title; Save As re-keys the same document, permitting extra pulses inside one minute and a false view_activated even though the active document did not change | Blocker for: Sprint 6 unit 2 / PR #102', '2026-07-18', '2026-07-18', 1, 5, 2, 'Fixed at PR #102 commit 5bd4c1d: throttle/view tracking now derives from CreationGUID with disjoint path/title fallbacks; Save As continuity and independent-document behavior are tested; detached-copy collapse was declared and planner-ratified.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (28, 'SC-028', 'Medium', '[Review] SetEnabled is not atomic with collection_disabled/enabled marker enqueueing; the heartbeat thread can emit after disabled or before enabled, so toggle gaps are not reliably framed | Blocker for: Sprint 6 unit 2 / PR #102', '2026-07-18', '2026-07-18', 1, 5, 2, 'Fixed at PR #102 commit 5bd4c1d: CollectorLifecycle serializes enabled transitions, marker enqueueing, emissions, heartbeat, and shutdown; deterministic interleaving tests prove gap framing and session_end-last ordering.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (29, 'SC-029', 'Medium', '[Review] TelemetryCollector.Start has no rollback after writer.Start/partial Subscribe, and RstApplication does not shut telemetry down if later OnStartup work fails; startup errors can leave a writer and event handlers alive with no shutdown owner | Blocker for: Sprint 6 unit 2 / PR #102', '2026-07-18', '2026-07-18', 1, 5, 2, 'Fixed at PR #102 commit 5bd4c1d: RunStartup registers rollback before subscribe and shuts down on partial failure without masking the original exception; RstApplication also shuts telemetry down when later OnStartup work fails.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (30, 'SC-030', 'Medium', '[Review round 2] CollectorLifecycle.TryEmit invokes the event factory while holding its transition lock; TelemetryCollector factories perform Revit API reads and full captures call BasicFileInfo.Extract, directly violating spec doc 5''s no-locks-held-across-API-calls rule and widening UI-thread lock hold time to header IO | Blocker for: Sprint 6 unit 2 / PR #102', '2026-07-18', '2026-07-18', 1, 5, 2, 'Closed after PR #102 round 2 at d33700a: all Revit/args/identity/header capture moved before CollectorLifecycle.TryEmit; under _gate remain only cached/session field population, throttle/view-gate in-memory admit, seq creation, and enqueue. CanAcquire preflight preserves hot-path cost while authoritative TryAcquire commits only after lifecycle admission. New tests cover gate refusal not reaching admit; lifecycle fixture teardown now always joins writer.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (31, 'SC-031', 'Medium', '[Review] Activity SVG monotoneTangents divides by zero when two open/sync points share a timestamp; the emitted path contains NaN control points and the curve disappears. Preserve/aggregate equal-x points before interpolation and add a regression over the shipped helper | Blocker for: Sprint 6 unit 4 / PR #103', '2026-07-18', '2026-07-18', 1, 5, 2, 'Resolved in PR #103 commit 3a8ee27: monotoneCubicPath collapses adjacent equal-x runs to mean y before tangent calculation, degrades one-distinct-x data to dots-only, and the shipped-helper regression asserts NaN-free finite output plus the all-one-x case.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (32, 'SC-032', 'Medium', '[Review round 3 at PR #103 commit c50af02] The keys-only close/sync propagation and sibling discrimination are fixed, but the cloud-null invariant still fails on the null/error branch. IdentityCapture.CaptureKeys and HealthCommand gate central-path capture with IsCloud != true; if IsModelInCloud throws, the guarded value is null and the code proceeds to GetWorksharingCentralModelPath, which Autodesk documents returns the cloud model path. TelemetryCollector.OnSyncStart repeats the fail-open condition for args.Location. This can emit central_path for a cloud model despite the spec requiring central_path null for cloud and every failed field read to remain null. Gate on known non-cloud (== false) and add a regression for unknown/null cloud classification at the capture seam. | Blocker for: Sprint 6 unit 4 / PR #103', '2026-07-18', '2026-07-18', 1, 5, 2, 'Resolved by PR #103 commit f60258f: DocumentIdentity.AllowsCentralPath(bool?) requires isCloud == false and is used by IdentityCapture.CaptureKeys, HealthCommand, and TelemetryCollector.OnSyncStart fallback. The null/false/true theory locks predicate semantics; code inspection verified all three call sites. Autodesk API docs confirm WorksharingCentralGUID throws outside eligible Revit Server models, so its retained guarded read cannot stamp a cloud central_guid.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (33, 'SC-033', 'High', '[Review] First-run notice writes a stale whole-prefs snapshot after a modal, so a concurrent Revit instance''s collection-off toggle can be overwritten back to enabled; notice marking must preserve concurrent preference changes (and be tested with two writers) | Blocker for: sprint 6 unit 5 consent', '2026-07-18', '2026-07-18', 1, 5, 2, 'Resolved by PR #104 commit d84a910: FirstRunNotice.MarkShown now uses TelemetryPrefs.Update under the shared cross-process lock, re-reads fresh state, and mutates only noticeShownUtc; merge/contention/timeout regressions cover the stale-write failure.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (34, 'SC-034', 'High', '[Review] HealthBridge gates the local collector callback on the shared prefs file already differing, so with two Revit instances a collector can remain on/off while SetTelemetryEnabled reports the requested opposite state; every successful user toggle must reconcile the local collector even when disk already has that value, with a two-instance-state regression | Blocker for: sprint 6 unit 5 consent', '2026-07-18', '2026-07-18', 1, 5, 2, 'Verified in PR #104 round 3 at 74b08bb: ConsentToggle.Apply serializes every click through TelemetryPrefs.Update and unconditionally invokes this process''s collector after successful persistence; failed persistence leaves it untouched. Real CollectorLifecycle regressions cover both disk/local-opposite states and idempotent matching-state reconciliation. No Major/Medium findings.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (35, 'SC-035', 'Medium', '[Telemetry conformance residual] JoinKey now includes normalized central_path, but RecoveryScanner and ActivityAggregator retire the pre-Save-As open entry only by previous_local_path matching a non-null captured LocalPath. If doc_opened local_path or doc_saved_as previous_local_path is null (an explicitly allowed identity-capture gap, including pathless/unsaved cases), a central-path-changing Save As leaves the stale old entry alive: a later real close removes only the new key, recovery synthesizes a false stale-key close, and aggregation accrues the old identity to session_end. Add an unambiguous lower-key/lineage fallback and regressions with the path field absent plus a real post-save close | Blocker for: Sprint 6 unit 6 / SC-035 conformance', '2026-07-18', '2026-07-18', 1, 5, 2, 'Resolved at PR #105 head 2083719: both RecoveryScanner.TrackOpenDocs and ActivityAggregator replay Save-As through an unambiguous creation-GUID fallback when the previous_local_path join is absent; the original path-gap + real-close regressions now prevent the stale pre-save entry / false synthetic close failure. A distinct candidate-scope defect is tracked separately as SC-037.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (36, 'SC-036', 'Low', '[Telemetry QA] Spec Build Plan step 6 VM pass is deferred: Revit 2025/2026/2027 runtime, kill/recovery, concurrent instances, file-central/cloud, toggle/ranges, and startup-latency remain unverified | Blocker for: final feature 2 QA gate (not sprint close)', '2026-07-18', NULL, 0, 5, 2, NULL, NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (37, 'SC-037', 'Medium', '[Review] ActivityAggregator tests lineage uniqueness only within current-file entries, so a keyed Save-As sibling can falsely retire the current file when previous_local_path is absent: doc_opened for current A (central A, creation G) is tracked; sibling B (central B, same G) is excluded by the current-file matcher; B→C doc_saved_as with no previous path scans only A, calls it the unique lineage candidate, and truncates A. Track enough all-open lineage state to make uniqueness global (as RecoveryScanner does), and add this keyed-sibling regression; the current ambiguity test strips the sibling central path and therefore misses the defect | Blocker for: Sprint 6 unit 6 / PR #105 SC-035 conformance', '2026-07-18', '2026-07-18', 1, 5, 2, 'Resolved at PR #105 head a522aa4: ReplaySession now tracks every open document in allOpenDocs, runs both previous_local_path and creation-lineage Save-As joins against that global view, and adds the exact keyed-sibling regression; the original SC-037 repro no longer truncates current A at sibling B''s save.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (38, 'SC-038', 'Medium', '[Review] ActivityAggregator''s global allOpenDocs close maintenance guesses through an allowed identity gap: with current A (central A + creation G) and keyed sibling B (central B + G), a B doc_closing whose central_path read failed carries only G; Matches falls through to G, allClosingIdToKey records a key absent from the global view, and DocClosed''s LatestOpenKey fallback closes A while leaving B stale. The new closed-sibling companion covers only a full-key close. Add the creation-only sibling-close regression and make ambiguous lower-key closes decline rather than retire the current file | Blocker for: Sprint 6 unit 6 / PR #105 SC-035 conformance', '2026-07-18', '2026-07-18', 1, 5, 2, 'Resolved at PR #105 b6cba77: LatestOpenKey and split closing maps were removed; the reported case with both siblings stored under distinct central-path keys now scans the full allOpenDocs identity set, sees two creation-GUID candidates, declines the close, and the regression asserts both current A and sibling B views. Residual exact-lower-key case is separately tracked as SC-039.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (39, 'SC-039', 'Medium', '[Review] Exact lower-level key hits bypass live-doc ambiguity: with A stored under central_path+G and a gapped sibling B stored under G, a creation-only close uses allOpenDocs.ContainsKey(G) to retire B even when the event belongs to A; sync_end similarly pairs pendingSyncs[G] without the unique-live-doc guard. Apply the general decline rule to exact lower-priority hits and add close/sync regressions for one higher-key sibling plus one gapped open | Blocker for: Sprint 6 unit 6 / PR #105 SC-035 conformance', '2026-07-18', '2026-07-19', 1, 5, 2, 'Resolved by PR #105 round 5 @ 491f2fb: ResolveOpenDoc returns a distinct ambiguity verdict; tied live lineage candidates veto exact lower-level close and sync_end hits, while non-ambiguous exact hits remain closable. Added red-at-b6cba77 close and sync regressions; 6/6 CI checks green. REV1 re-review: 0 Major / 0 Medium / 0 Low.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (40, 'SC-040', 'Medium', '[Telemetry conformance] ActivityAggregator collapses two live docs that share the same gapped lower-level JoinKey, erasing ambiguity before close/sync resolution; exact hits can then retire/pair despite rulings #171/#177 | Blocker for: Sprint 6 spec freeze', '2026-07-19', '2026-07-19', 1, 5, 2, 'Resolved by PR #106 through aa9a5f3: allOpenDocs preserves one entry per live document, close/sync/Save-As ambiguity is judged over live docs, unique rejecting-sibling and cross-bucket winner paths are covered; round-3 review clean with CI green.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (41, 'SC-041', 'Medium', '[Telemetry review] ActivityAggregator''s new per-key live-doc list over-declines a uniquely attributable endpoint: ResolveOpenDoc finds one consistent doc, then Count > 1 marks it ambiguous solely because an explicitly rejected sibling shares the JoinKey; close/sync undercount and SC-040''s required later-unique resolution remains unproven | Blocker for: Sprint 6 unit 7 / spec freeze', '2026-07-19', '2026-07-19', 1, 5, 2, 'Resolved at PR #106 commit ae11d12: ResolveOpenDoc returns the unique winning list element; duplicate-key close retires only that element and preserves rejecting siblings; close and sync regressions cover the original same-bucket SC-041 case.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (42, 'SC-042', 'Medium', '[Telemetry review] doc_closed''s one-element exact-JoinKey shortcut overrides ResolveOpenDoc''s unique winner even when that exact-bucket doc explicitly rejects a present higher identity key; the wrong sibling retires and the actual doc runs to session_end | Blocker for: Sprint 6 unit 7 / spec freeze', '2026-07-19', '2026-07-19', 1, 5, 2, 'Resolved by PR #106 commit aa9a5f3: doc_closed now consults ResolveOpenDoc first and uses the one-element exact-JoinKey path only when the resolver has no candidate; cross-bucket regression asserts the winner closes and rejecting sibling survives.', NULL, 0);
INSERT INTO flags (flag_id, display_name, priority, description, created_date, resolved_date, resolved, shell_id, feature_id, resolution_notes, parent_flag_id, is_deleted) VALUES (43, 'SC-043', 'Medium', '[Telemetry conformance] ActivityAggregator keeps a current-file interval alive after that file''s uniquely attributed close when a higher-identity sibling sharing the lower JoinKey is explicitly rejected by the current-file matcher | Blocker for: Sprint 6 conformance clean/spec freeze', '2026-07-19', '2026-07-19', 1, 5, 2, 'Verified on PR #107 head ff87b4f: ActivityAggregator stores Matched per live OpenDoc, retires current-file intervals when the last matching element leaves on close and Save-As paths, preserves rejecting siblings for resolver multiplicity, and the SC-043 A=1.0h/B=1.5h plus Save-As regressions are green in CI.', NULL, 0);

