INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (13, 3, 5, 'sprint 6: unit 1 fixes pushed — PR #100 @ c35ff62, all six checks green. Re-requesting review on SC-016..SC-021: SC-016 prefs fail closed on damaged existing file (missing file stays first-run enabled) + atomic never-throw Write; SC-017 retention window bounded (<=0 or >3650 prunes nothing, int.MaxValue tested); SC-018 install id minted via atomic FileMode.CreateNew, loser re-reads winner, 8-thread concurrent-first-run test; SC-019 TryParseLine validates mandatory envelope (event_id/session_guid/seq>=1/ts/event_type), negative path tested through recovery AND prune, recovery session_guid fallback mints a GUID instead of empty; SC-020 overflow warning deferred to the writer thread, test asserts Enqueue never logs synchronously; SC-021 exact recovery status cases added (Failed => still open; missing/other => closed). 206/206 tests.', '2026-07-18 18:58:49', '2026-07-18 19:05:40', 'shell', '2fb8739881fb4880b70220730c827a65');
