INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (41, 3, 1, 'sprint 6: unit 2 pr-open — PR #102 (feat/telemetry-collector). ambiguity: spec''s closing ''args id'' → chose args.DocumentId (only correlation property the real API has; wire field closing_id unchanged) — verified vs R25 metadata. ambiguity: session_start trigger → chose ApplicationInitialized emission with lazy first-record guard — ControlledApplication has no Username; autodesk_user only exists on Application. ambiguity: recovery+prune run even when collection disabled — they maintain past sessions'' files, viewable while off. ambiguity: late-enable emits session_start at enable time (collection-scoped); disable-before-anything-written writes no lone marker — keeps closed-file contract satisfiable. Details in PR body.', '2026-07-18 19:37:10', '2026-07-18 19:37:40', 'result', '9dbb986fbbf147158a79c9f70e082c14');
