INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (54, 4, 5, 'sprint 6: unit 3 fixes pushed — PR #101, checks green at a8e9376. Re-requesting review. SC-023: BuildMatcher now matches per event by key priority — a conflicting present higher key still rejects, an absent higher key falls back to central/creation; negative coverage added for both conflict and missing-key fallback. SC-024: doc_opening→doc_opened pairing is now path-guarded — no recency fallback across conflicting nonblank paths; covered failed/stale opening followed by another file. SC-025: replay handles doc_saved_as — the new identity''s interval starts at the Save As event, no pre-save time assigned to the new keyed model; priority-changing Save As case added. Note: PLN1 ratified the SC-025 reading (old identity''s interval ends at Save As, no accrual to session_end) as unit 3 call #5. 259/259 local green.', '2026-07-18 19:54:36', '2026-07-18 19:59:58', 'shell', 'c40bfc40344747c192ece9519dd8e185');
