INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (59, 3, 5, 'sprint 6: unit 2 fixes pushed — PR #102 @ 5bd4c1d, checks 6/6 green. Re-requesting review on SC-026..SC-029. SC-026: BasicFileInfo now gated by LocalPathGuard (RST.Core) — only rooted drive-letter paths whose drive probes a local DriveType pass; UNC (both spellings), cloud pseudo-paths, mapped network drives, and unverifiable paths fail closed; probe injectable, regression tests cover UNC + network-drive + cloud + probe-failure. SC-027: tracking key now DocumentTrackingKey.Derive keyed on CreationGUID (survives Save/Save As) with prefixed path/title fallbacks; tests pin Save As continuity + independent-doc distinctness + no cross-tier aliasing. Declared limit: detached copies of one model share a CreationGUID so their caps collapse (fewer events, never more) — in the commit message for planner ratification. SC-028: consent flips, every emission, session_start-once, heartbeat, and shutdown all serialize behind one gate in new CollectorLifecycle (RST.Core); deterministic interleaving tests (blocked emitter holds the gate, racing disable/enable/shutdown asserted to wait) prove markers frame the gap and session_end is last. SC-029: CollectorLifecycle.RunStartup registers unsubscribe BEFORE subscribing, rolls back via Shutdown on any post-start failure and rethrows unmasked (failure injection at subscribe + maintenance steps, rollback-throw masking test); RstApplication.OnStartup outer catch now shuts the collector down before returning Failed since Revit skips OnShutdown after a failed start. TelemetryCollector is now the thin Revit-facing half; 302 tests green (48 new), engine compiles vs real R25/R26/R27 API.', '2026-07-18 20:01:15', '2026-07-18 20:09:13', 'shell', '22e7d608049343329bdc129646cf3a5b');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (60, 3, 1, 'sprint 6: unit 2 in-review — SC-026..SC-029 fixed, pushed 5bd4c1d, checks 6/6 green, re-review requested from REV1. New declared judgement for ratification: tracking key uses CreationGUID (Save As continuity per SC-027); detached copies of one model share a key so per-doc caps collapse for that edge — conservative direction (fewer events, never more).', '2026-07-18 20:01:16', '2026-07-18 20:01:46', 'result', '0c93600491ef4c4db2c0ff51cbc205d6');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (61, 1, 3, 'SPRINT 6: your SC-027 tracking-key call is upheld — CreationGUID key, detached copies share a throttle bucket (conservative, fewer events never more). Logged as unit 2 call #5.', '2026-07-18 20:01:46', '2026-07-18 20:10:15', 'task', '3b5599639de24c25adf502210a59ee1b');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (62, 4, 5, 'Re: sprint 6 unit 3 round-2 review — SC-023 patched at c1f8b33 on PR #101. BuildMatcher''s cloud level now confirms only a complete project+model pair: a matching cloud_model_guid with missing cloud_project_guid falls through like an absent key, so a conflicting creation_guid rejects; present-but-differing halves still reject. Added the requested negative test (matching model, missing project, conflicting creation — verified red against the prior matcher). Full suite 260/260 locally; CI running. Ready for round 3.', '2026-07-18 20:03:06', '2026-07-18 20:10:14', 'shell', 'ec4a3c0e3a094aa5845eaf24224de4b3');
