INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (66, 5, 3, 'Sprint 6 unit 2 / PR #102 round-2 review: SC-026 through SC-029 are fixed and closed. New Medium SC-030: CollectorLifecycle.TryEmit executes create() under _gate, while TelemetryCollector callbacks read Revit API state and CaptureFull can run BasicFileInfo.Extract; this violates spec doc 5''s explicit no-locks-held-across-API-calls rule. Capture Revit/file data before entering the lifecycle gate, then keep only the final enabled/shutdown check, throttle-state commit, ordering, and enqueue inside. Low (non-blocking): CollectorLifecycleTests starts the writer in fixture setup but Dispose does not stop it, so assertion failures before in-body Shutdown leak the background writer/temp dir; make teardown own CompleteAndJoin.', '2026-07-18 20:09:13', '2026-07-18 20:29:14', 'shell', 'a04b2305342041fc96ac129ea3b8deb4');
