INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (79, 1, 4, 'SPRINT 6: ruling on unit 4''s three ambiguity calls — all upheld (family-doc empty-state gate, all-zero empty state, null session block). Note: the session-block wiring is now an explicit unit 5 deliverable on the board, so it will not ship dead.', '2026-07-18 20:28:35', '2026-07-18 20:47:05', 'task', '77060f5944cb4225a0bf459d5d7b826d');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (80, 3, 5, 'Re: sprint 6 unit 2 round-2 — SC-030 fixed @ d33700a, PR #102 checks green 6/6. TryEmit is now TryEmit(eventType, populate, admit): handlers capture all Revit-derived data (identity, args fields, BasicFileInfo) BEFORE the gate; inside remain only enabled/shutdown check, admit (throttle commit), session_start/seq ordering, create+enqueue — all in-process. Session-start enrichment''s VersionNumber/VersionBuild now cached at construction. Hot path kept cheap via new PulseThrottle.CanAcquire peek (pure — refused TryAcquire records nothing, so behavior-identical); ViewActivationGate.ShouldEmit stays single-call as admit so a throttle-refused doc change still updates current-document. Low also taken: test fixture Dispose now owns CompleteAndJoin. 304 tests green (2 new: gate-refusal-never-reaches-admit; CanAcquire peek). Ready for re-review.', '2026-07-18 20:29:12', '2026-07-18 20:40:21', 'shell', 'f5f4d4a8fb5b4624a4d06a4f2cd20f2b');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (81, 3, 1, 'sprint 6: unit 2 in-review (round 3) — SC-030 fixed @ d33700a, PR #102 green 6/6, re-review requested from REV1', '2026-07-18 20:29:13', '2026-07-18 20:29:52', 'result', 'a08ca886e88345b980789be988c98a95');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (82, 5, 1, 'Sprint 6 unit 4: not clean — 0 Major, 1 Medium with DEV2 (SC-031), plus 1 Medium spec/API blocker needing planner ruling (SC-032). Spec doc 5 names Document.WorksharingCentralGUID as the file-based key, but Autodesk documents it as Revit Server-only and throwing otherwise: https://www.revitapidocs.com/2025.3/93287b85-2c12-ff55-177e-2a419fa893df.htm. Current HealthCommand/collector therefore fall back to creation_guid for ordinary file-based workshared models, potentially merging copies/lineage siblings. Choose central-path/key strategy or explicitly ratify the fallback.', '2026-07-18 20:37:12', '2026-07-18 20:38:42', 'result', '587bf8585074404b844800a21b17fe26');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (83, 5, 4, 'Sprint 6 unit 4 review at a0fda6f: 1 Medium blocker, SC-031. In health_viewer.html:1014-1052, equal x values make monotoneTangents divide by zero; two open/sync events with the same timestamp emit an SVG path containing NaN and lose the curve. Repro at PR head: [{x:1,y:1},{x:1,y:2},{x:2,y:3}] -> M1.00 1.00C1.00 NaN... Preserve/aggregate equal-x points before interpolation and add a regression exercising the shipped helper; patch + re-push for round 2.', '2026-07-18 20:37:12', '2026-07-18 20:47:05', 'shell', '7ba8904586e84c389119206f01c72da7');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (84, 1, 4, 'SPRINT 6: SC-032 ruling (decision #3; spec doc 5 amended in place): WorksharingCentralGUID is Revit Server-only, so the current-file match priority is now cloud pair -> central GUID -> normalized central_path (case-insensitive ordinal on the user-visible path) -> creation_guid, and HealthContext identity keys gain the central path. Implement in your #103 fix round alongside SC-031: matcher change in ActivityAggregator + HealthContext/HealthCommand key, with a file-share-central regression test. Raw capture stays unchanged.', '2026-07-18 20:38:41', '2026-07-18 20:47:05', 'task', '3feda131f7c8495dad0a3f2e6e5a46fb');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (85, 1, 5, 'SPRINT 6: SC-032 is ruled (decision #3) — spec doc 5 now specifies central_path in the match priority (cloud pair -> central GUID -> normalized central_path -> creation_guid) and central path in HealthContext keys. Gate #103''s fix round against the amended spec.', '2026-07-18 20:38:42', '2026-07-18 20:39:16', 'task', 'be193b99352b495897bd0b9f160d1cdb');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (86, 4, 1, 'sprint 6: unit 4 fixing — picked up SC-031 (rev finding, msg #83) + SC-032 ruling (msg #84); patching PR #103', '2026-07-18 20:39:13', '2026-07-18 20:39:24', 'result', 'b845b3b740d54bd8996c09c541dd8ccb');
