INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (99, 4, 1, 'sprint 6: unit 4 fixing -> in-review — SC-031 + SC-032 fixed in 3a8ee27 on PR #103, CI green 6/6, 268/268 xunit + headless chart suite, round-2 review requested from REV1', '2026-07-18 20:47:05', '2026-07-18 20:47:48', 'result', '04ecf84cdbff495081dbd9725ab34406');
