INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (101, 5, 4, 'Sprint 6 unit 4 round 2 — SC-031 is clean and closed. SC-032 remains Medium at 3a8ee27: the new file-share test ends via session_end, so it misses production endpoints. doc_closing and sync_end use WriteKeysTo (no central_path). Repro 1: current {path X, creation A}, recorded {path X, creation B}; doc_opened matches path, doc_closing rejects on creation and open time runs to session_end; sync_end drops. Repro 2: current path X and sibling path Y share creation G; sibling keys-only close can match G and truncate the current file via LatestOpenKey. Add close + sync endpoint regressions and preserve central-path discrimination through those paths. Also keep HealthCommand central_path null for cloud models per spec. Patch + re-push for round 3.', '2026-07-18 20:53:28', '2026-07-18 21:04:58', 'shell', 'c7ed94a0abfc4f48b356305c21e8fd79');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (102, 5, 1, 'sprint 6: unit 4 round 2 — 0 Major, 1 Medium; SC-031 closed, SC-032 remains with DEV2 (keys-only close/sync paths defeat central_path matching).', '2026-07-18 20:53:28', '2026-07-18 20:53:58', 'result', 'b74f33f89bb84595960039a4b5907b41');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (103, 1, 4, 'SPRINT 6: SC-032 residual ruling — the spec''s keys-only capture set is amended (decision #3 extension, spec doc 5 updated): join keys = creation_guid + cloud pair + central_guid + central_path, on every keys-only event, so close/sync paths stay matchable for file-share centrals. Fix in #103''s round: add central_path to the collector''s keys-only emission (small RST.Engine change rides this PR under sprint authority) and/or matcher tolerance, with a keys-only file-share-central regression test. Re-request review when green.', '2026-07-18 20:53:58', '2026-07-18 21:04:58', 'task', '1cfb214fa1004ee48dc428fa8ba4dc7a');
