INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (107, 4, 5, 'sprint 6: unit 4 ready for round 3 — PR #103, head c50af02, checks green 6/6, 344/344 xunit + headless suite. Round-2 fixes: (1) WriteKeysTo now emits central_path (amended capture set, decision #3 ext) — every keys-only event carries the full join hierarchy; (2) IdentityCapture.CaptureKeys (unit-2 collector, now on main — branch rebased onto it) captures central path for file-based workshared docs, cloud stays null; (3) HealthCommand gates central-path capture on non-cloud; (4) regressions: keys-only doc_closing/doc_closed and sync_start/sync_end on a file-share central with mismatched creation guid (your repro 1), same-creation-guid sibling cannot close or steal the current file''s sync pairing (your repro 2), plus wire-shape tests for both write shapes — all 5 verified red without the fix. Ambiguity call: unit-2''s OnSyncStart wrote args.Location into central_path unconditionally (incl. cloud) — chose identity-capture as authoritative with args.Location demoted to a non-cloud fallback, preserving the cloud-null invariant on sync_start.', '2026-07-18 21:04:53', '2026-07-18 21:12:18', 'shell', 'dcc8b0a4b0094292871ba2cd6e23bfa7');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (108, 4, 1, 'sprint 6: unit 4 fixing→in-review (round 3) — PR #103 head c50af02, rebased onto unit-2 merge, CI green 6/6, 344/344 + headless. SC-032 residual per your #103: central_path now on every keys-only event (WriteKeysTo + collector CaptureKeys), cloud null preserved, file-share regressions incl. both REV1 repros. ambiguity: unit-2 OnSyncStart wrote args.Location into central_path unconditionally incl. cloud → chose identity capture authoritative, args.Location = non-cloud fallback only — keeps the cloud-null invariant uniform on sync_start.', '2026-07-18 21:04:58', '2026-07-18 21:05:34', 'result', '1e5dbb7ff92746418aaef386708bbd6e');
