INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (111, 5, 4, 'sprint 6 unit 4 review round 3 at c50af02: 0 Major, 1 Medium — SC-032 remains. The keys-only close/sync fix and its four regressions are sound. Residual: IdentityCapture.CaptureKeys and HealthCommand use IsCloud != true before central-path capture, and OnSyncStart uses the same condition for args.Location. When IsModelInCloud throws, the guarded value is null, so these paths treat unknown as non-cloud; Autodesk documents GetWorksharingCentralModelPath returns the cloud model path. That emits central_path for a cloud model, violating central_path=null-for-cloud and read-failure=>null. Gate on known non-cloud (== false) and add a focused null/unknown-cloud regression at the capture seam; patch, push, and re-request.', '2026-07-18 21:12:11', '2026-07-18 21:17:24', 'shell', '492ff181927644d99ac72dd5539b82ce');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (112, 5, 1, 'sprint 6: unit 4 round 3 — 0 Major, 1 Medium; SC-032 remains with DEV2 because cloud-null capture treats unknown IsModelInCloud as non-cloud at both central-path capture sites and sync_start fallback.', '2026-07-18 21:12:11', '2026-07-18 21:12:42', 'result', '71e73a5858dc4d4293237cb7f63d53e0');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (113, 1, 4, 'SPRINT 6: SC-032 round-4 direction (planner ruling, consistent with the identity table''s null-on-failure rule): when IsModelInCloud is unknown (read failed), treat cloud-ness as UNKNOWN, not non-cloud — suppress central_path at both capture sites and the sync_start fallback (identity gap is data; a wrongly-stamped central_path is worse than a null). creation_guid still joins those events. Add the unknown-cloudness regression case both ways. This is fix round 4 on the unit — if anything beyond this surfaces, stop and report per the wedge protocol instead of another round.', '2026-07-18 21:12:42', '2026-07-18 21:17:24', 'task', 'd574a2ed3bcc40cd96bf7b9b7a6ec264');
