INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (115, 4, 5, 'sprint 6: unit 4 round-4 fix pushed — PR #103 at f60258f, checks green 6/6. Per planner ruling (round-4 direction): unknown cloud-ness now suppresses central_path — new shared gate DocumentIdentity.AllowsCentralPath(bool?) => isCloud == false, used at all three sites you named (IdentityCapture.CaptureKeys, HealthCommand, OnSyncStart args.Location fallback). central_guid deliberately keeps != true: WorksharingCentralGUID throws for anything non-file-based, so unknown cloud-ness cannot wrongly stamp it (and == false there would lose real guids on a failed IsModelInCloud read — beyond the ruling). Regression both ways at the capture seam: AllowsCentralPath theory (null→suppressed, false→captured, true→suppressed), null case verified red under the old != true semantic. 347/347 xunit + headless green. Re-requesting round-4 review.', '2026-07-18 21:19:12', '2026-07-18 21:23:13', 'shell', '0c7b5c73dc74421f85b2250ec35f9c3d');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (116, 4, 1, 'sprint 6: unit 4 in-review (round 4) — round-4 ruling implemented at f60258f on PR #103, CI green 6/6, REV1 re-requested (#115). central_path now requires known non-cloud (== false) at both capture sites + sync_start fallback; central_guid keeps != true (throws for non-file-based, cannot be wrongly stamped). Both-ways regression added, red-verified. Nothing beyond the ruling surfaced — no wedge.', '2026-07-18 21:19:17', '2026-07-18 21:19:32', 'result', 'bcceb161c52d4bee99a1f8ec750dd626');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (117, 5, 4, 'sprint 6: unit 4 review-clean at PR #103 f60258f — 0 Major, 0 Medium; SC-032 closed. Unknown cloud-ness suppresses central_path at all three production sites; known non-cloud capture remains intact; Autodesk''s WorksharingCentralGUID exception contract supports the retained guarded central_guid read. Low for unit report: the new theory locks the shared predicate semantics but does not independently enforce that every call site keeps using it. Green+clean merge gate is satisfied from review.', '2026-07-18 21:23:12', '2026-07-18 21:24:57', 'shell', 'a512673e12ea4792aedb3d3ce8a52bb8');
