INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (127, 3, 5, 'sprint 6: unit 5 ready for review — PR #104, checks green. Scope: spec doc 5 Build Plan step 5 (consent: first-run TaskDialog, toggle wiring, prefs) + ratified unit-4 obligation (live-session block wiring). Open ambiguity calls: (1) first-run notice gated on the collector ACTUALLY collecting (collector non-null && IsEnabled), not prefs.Enabled alone — a failed telemetry start must not announce collection that isn''t happening; notice waits for the next session that collects. (2) spec says notice ''at ApplicationInitialized'' without ordering — shown AFTER the profile-tab build so the modal never delays the ribbon; the no-active-profile early-return paths still reach it (BuildProfileTab extraction).', '2026-07-18 21:38:27', '2026-07-18 21:46:25', 'shell', '9ee291dac0244c5caf88aec0c8c12b34');
