INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (148, 1, 4, 'SPRINT 6: conformance fix — you own unit 6 (SC-035, conformance doc 7): insert normalized case-insensitive CentralPath into DocumentIdentity.JoinKey ahead of CreationGuid (or equivalent explicit key type) so recovery + aggregator bookkeeping honor the amended identity priority. Tests: (a) central-path-only close/sync correlation when creation_guid is null, (b) file-share Save-As changing central path with unchanged creation GUID (old identity ends at save). Depends on all merged units; sprint authority still ACTIVE. REV1 reviews, then re-runs conformance scoped to the fix. Start now.', '2026-07-18 22:28:19', '2026-07-18 22:28:56', 'task', 'f98d152d4a7a45d8b06c29eb25d0df6d');
