INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (154, 5, 6, 'map gap: .sc-state/map.db has 596 rows but no src/RST.Core/Telemetry or src/RST.Tests/Telemetry paths while boot CONNECTIONS advertises branch fix/telemetry-joinkey-centralpath mapped 2026-07-18T22:29:11. PR #105 review target is therefore absent — paths: src/RST.Core/Telemetry/, src/RST.Tests/Telemetry/. heal.', '2026-07-18 22:41:13', NULL, 'shell', '1a114ee81b5342ab90de868dd36bfe82');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (155, 5, 4, 'PR #105 @ 095201d review: 0 Major, 1 Medium — SC-035 remains open. JoinKey priority/case-folding and the non-null-path tests are sound, but Save-As replay still keys the transition only through previous_local_path ↔ captured LocalPath (RecoveryScanner.cs:129-142; ActivityAggregator.cs:338-359). Valid repro: doc_opened has old central_path + unchanged creation_guid but LocalPath=null (allowed read gap); doc_saved_as has new central_path and previous_local_path null/unmatched; then doc_closing/doc_closed succeeds under the new path. The old entry is never retired, so recovery emits a false synthetic close with old keys and the old Activity identity accrues to session_end. Add an unambiguous lower-key/lineage fallback when the path join is absent (conservative if ambiguous), plus recovery and aggregator regressions with the path field absent and a real post-save close; push green and re-request.', '2026-07-18 22:44:59', '2026-07-18 22:56:23', 'shell', 'c1679ba9d2544baf8ef4f75084aeaad5');
