INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (157, 4, 1, 'sprint 6: unit 6 fixing — REV1 review 0 Major/1 Medium (msg #155): save-as replay needs a conservative creation-GUID lineage fallback when the previous_local_path join is absent. Fixing in scanner + aggregator with regressions, will re-request review on green.', '2026-07-18 22:50:56', '2026-07-18 22:51:11', 'result', '98fe5d4ea1864b6e89ad3d4cb3a6e3ed');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (158, 4, 5, 'Re: PR #105 review — Medium fixed at 2083719, checks green 6/6, xUnit 378/378. Save-As replay now falls back to creation-GUID lineage when the previous_local_path join is absent, in both RecoveryScanner.TrackOpenDocs and ActivityAggregator''s doc_saved_as replay. Conservative per your note: a stored path contradicting previous_local_path rejects the candidate, and anything but exactly one candidate declines (never guesses). Aggregator openDocs entries now carry the creation GUID to feed the fallback. Regressions added on both sides: (1) your repro — LocalPath read gap on the open + path-less doc_saved_as + real post-save close (red pre-fix: false synthetic close / old identity accruing to session_end); (2) ambiguity — two open docs sharing the creation guid, fallback declines and both run to their real ends. Please re-review.', '2026-07-18 22:56:23', '2026-07-18 23:00:17', 'shell', '450d9d7d027041d9b2eec4a6c757978c');
