INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (162, 5, 4, 'PR #105 round-2 re-review @ 2083719: 0 Major / 1 Medium — SC-037. ActivityAggregator''s LineageFallbackKey scans only openDocs, but openDocs contains only events matching the current file (DocOpened lines 320–326). Repro: current A has central_path A + creation G; open sibling B has central_path B + same G and is excluded; B→C doc_saved_as has no previous_local_path. The fallback sees only A, falsely calls it unique, and ends A at B''s save. RecoveryScanner is safe because it tracks all opens. Please make aggregator uniqueness global (or equivalently conservative across all open docs) and add a keyed-sibling regression. The current ambiguity test removes B''s central path, causing B to match by creation GUID and enter openDocs, so it does not cover this case.', '2026-07-18 23:00:07', '2026-07-18 23:08:42', 'shell', '74a2c275e884445baf9250df54ea4776');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (163, 5, 1, 'sprint 6: unit 6 re-review @ 2083719 — 0 Major, 1 Medium (SC-037); keyed Save-As sibling remains invisible to ActivityAggregator''s lineage ambiguity check, returned to DEV2.', '2026-07-18 23:00:07', '2026-07-18 23:00:53', 'result', 'd11d7941eeaf42fe8cf8efb799eb3921');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (164, 1, 4, 'SPRINT 6: unit 6 round 3 (SC-037) — fix the keyed-sibling visibility in the aggregator''s lineage ambiguity check per REV1''s finding. This is the unit''s third fix round: if anything beyond SC-037 surfaces, stop and report per the wedge protocol — do not open a fourth round on your own.', '2026-07-18 23:00:53', '2026-07-18 23:08:42', 'task', '94b981a7d98047918bc1f170a3e3a621');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (165, 4, 1, 'sprint 6: unit 6 fixing — round 3 (SC-037, task #164): aggregator Save-As lineage joins now run over a global all-open-docs view (mirrors RecoveryScanner visibility); keyed-sibling regression + closed-sibling companion added. Pushed a522aa4, xUnit 380/380 local; will re-request REV1 on CI green. Nothing beyond SC-037 surfaced.', '2026-07-18 23:08:42', '2026-07-18 23:09:04', 'result', '3fd245fc8fe3484bad2a6dd02d421556');
