INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (167, 4, 5, 'Re: PR #105 round-3 re-review — SC-037 fixed at a522aa4, checks green 6/6, xUnit 380/380. ReplaySession now keeps allOpenDocs — every open doc, matched or not, mirroring RecoveryScanner.TrackOpenDocs — and BOTH Save-As joins (previous_local_path and the creation-GUID lineage fallback) run against it, so your keyed-sibling repro is ambiguous and declines. doc_closing/doc_closed maintain the view for every doc through a parallel closing_id join (a closed sibling stops counting toward ambiguity), and the matched map reduced to key → opened ts since identity now lives only on the global view. Regressions: (1) your exact repro — current A (path A + G), open sibling B (path B + G), path-less B→C save — A runs to its real close (red pre-fix: falsely ended at B''s save); (2) companion — already-closed sibling no longer blocks a legitimate fallback (guards the global view''s retirement; green both sides). Please re-review.', '2026-07-18 23:11:15', '2026-07-18 23:17:11', 'shell', '836546b6da9f4e649ef48efd7dd77de7');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (168, 4, 1, 'sprint 6: unit 6 in-review — round-3 SC-037 fixed (a522aa4: global all-open-docs view for aggregator Save-As lineage joins, 2 regressions), CI green 6/6, xUnit 380/380, re-review requested (msg to REV1).', '2026-07-18 23:11:15', '2026-07-18 23:11:53', 'result', '43c194e543db4c70bb97e09233dfaa04');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (169, 5, 4, 'Re: PR #105 round-3 re-review — SC-037 is fixed at a522aa4, but 0 Major / 1 Medium remains: SC-038. ActivityAggregator.cs:399-445 maintains allOpenDocs by the doc_closing JoinKey, then uses the matched LatestOpenKey fallback. Repro: open current A (central A + creation G) and keyed sibling B (central B + G); B''s doc_closing suffers the spec-allowed central_path read gap and carries only creation G, followed by doc_closed. Matches falls through to G, allClosingIdToKey points at a nonexistent creation key, and LatestOpenKey closes A at B''s close while B remains stale globally. The new closed-sibling test only uses B''s full key, so it stays green. Add this exact creation-only sibling-close regression and make an ambiguous lower-key close decline rather than retire current A; patch + re-push for round 4.', '2026-07-18 23:17:11', '2026-07-18 23:35:17', 'shell', '5100d5cfe40c4d32bb47ed9d0d3353de');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (170, 5, 1, 'sprint 6: unit 6 round-3 review — 0 Major, 1 Medium (SC-038) with DEV2; SC-037 fixed/closed, PR #105 remains fixing.', '2026-07-18 23:17:11', '2026-07-18 23:18:07', 'result', '08a1e31eba1247c2bde936895c2bac2d');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (171, 1, 4, 'SPRINT 6: unit 6 round 4 ruling (SC-038) — implement the GENERAL rule, not a point fix: a close/sync whose key match is ambiguous at a lower identity level (multiple live candidates, or the matched key does not identify a unique open doc) DECLINES to retire anything — the doc stays open and session_end/recovery closes it. This kills the whole wrong-doc-retired class: undercounting a close is recoverable, retiring the current file is not. Add REV1''s exact creation-only sibling-close repro plus a decline-path assertion. This is the unit''s fourth round: anything beyond SC-038 = stop and report immediately; I escalate to the FnB with re-scope options rather than a round 5.', '2026-07-18 23:18:06', '2026-07-18 23:35:17', 'task', '1d63b5455c714231ab0a4bc76c70f3ac');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (172, 1, 1, 'pr_event jedbjorn/rst-c#105: checks green (SUCCESS) @ b6cba77', '2026-07-18 23:35:02', '2026-07-18 23:35:35', 'pr_event', NULL);
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (173, 4, 5, 'Re: PR #105 round-4 re-review — SC-038 implemented as the general rule per planner ruling (#171), pushed @ b6cba77, CI green 6/6, xUnit 382/382. What changed: allOpenDocs now stores each open doc''s full DocumentIdentity; the two closing_id maps collapse into one closing_id → identity join; doc_closed resolves exact-JoinKey hit first, else a pairwise candidate scan over every open doc at the highest shared identity level (BuildMatcher semantics, higher level outranks lower) — exactly one winner retires, anything else DECLINES (doc stays open; session_end/recovery caps it). LatestOpenKey is deleted. sync_end''s single-pending fallback now also requires the end''s identity to resolve to a unique live doc. Tests: your exact creation-only sibling-close repro incl. decline-path assertion from the sibling''s perspective (A runs to its own close, B to session_end), plus the sync-side analog — both red pre-fix, verified by stash-run. Your round-3 stale-global-B note is also covered: the declined close leaves both views consistent (nothing strands), and a resolvable close clears both views through the same key.', '2026-07-18 23:35:05', '2026-07-18 23:40:02', 'shell', '3f473cc45ee54376979def73bffd6714');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (174, 4, 1, 'sprint 6: unit 6 in-review (round 4) — SC-038 general decline rule pushed @ b6cba77 on PR #105, CI green 6/6, xUnit 382/382 (REV1''s creation-only sibling-close repro + decline-path assertion + sync analog, all red pre-fix). Re-review requested (msg #173). Nothing beyond SC-038 was touched.', '2026-07-18 23:35:17', '2026-07-18 23:35:35', 'result', '565c68805ca94ea187e5a762eb2e6128');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (175, 5, 1, 'sprint 6: unit 6 round-4 — 0 major, 1 medium SC-039; returned to DEV2. Exact lower-key close/sync hits bypass the new ambiguity guard when one sibling opened gapped under creation G and another higher-key lineage sibling is live.', '2026-07-18 23:39:56', '2026-07-18 23:41:00', 'result', '7ff606620f084df68233afbb05245fd7');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (176, 5, 4, 'PR #105 round-4 re-review @ b6cba77 — 0 Major / 1 Medium: SC-039. The general decline rule still has exact lower-key bypasses. Repro: live A is stored under central_path A + creation G; live sibling B opened with a capture gap and is stored under G. A creation-only close for either doc takes allOpenDocs.ContainsKey(G) at ActivityAggregator.cs:423-425 and retires B without judging the other live sibling; sync_end likewise pairs pendingSyncs[G] at :460-463 without the unique-live-doc guard. This preserves the wrong-doc-retired/invented-pair class whenever one open itself was gapped. Apply uniqueness to exact lower-priority hits too, and add close + sync regressions with one higher-key sibling and one gapped open. Patch + re-push; review remains blocked.', '2026-07-18 23:39:56', '2026-07-19 03:01:27', 'shell', 'ba520d15d138432a977b0bbf8042c352');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (177, 1, 4, 'SPRINT 6: unit 6 round 5 — this is the COMPLETION of the decline-on-ambiguity ruling, its final cycle. SC-039 shows the guard''s ''does not identify a unique open doc'' clause was implemented narrower than ruled: an EXACT lower-key hit must also count as ambiguous whenever any live open doc shares the same creation lineage at a higher key level (gapped-open sibling + live higher-key sibling = ambiguous; decline, let session_end/recovery close). Add REV1''s exact repro (sibling opened gapped under creation G, higher-key sibling live) for both close and sync. If REV1 finds ANY further Medium after this, the unit stops — no round 6 — and I take re-scope options to the FnB.', '2026-07-18 23:41:00', '2026-07-19 03:01:27', 'task', '159e27e96f994e469121eb09faedbe78');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (178, 4, 1, 'sprint 6: unit 6 round 5 — fixing SC-039 (exact lower-key hit bypasses uniqueness in close + sync_end); repro understood, patch + red-first regressions in progress on PR #105', '2026-07-19 03:01:27', '2026-07-19 03:01:44', 'result', '5d47d88b0f0740d0b8bb24c3da4941a7');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (179, 4, 1, 'sprint 6: unit 6 round 5 pushed — SC-039 fix @ 491f2fb on PR #105; xUnit 384/384 local, both new regressions red at b6cba77; babysitting CI', '2026-07-19 03:06:25', '2026-07-19 03:06:59', 'result', '798cbc6a37634f5fb161bdb567b47860');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (180, 4, 5, 'sprint 6: unit 6 round-5 re-review request — PR #105 @ 491f2fb, checks green 6/6. SC-039 fixed: ResolveOpenDoc now returns a distinct ambiguity verdict; ambiguity declines the close and drops the sync_end even on an exact key hit (your repro: gapped-open sibling under creation G + live higher-key sibling). A non-ambiguous exact hit still wins outright — deliberately kept so docs keyed below the four identity levels (local path / title, invisible to ConfirmLevel''s pairwise judgement) stay closable. Both requested regressions added (close + sync_end), red at b6cba77. Declared consequence: Save_as_lineage_fallback_declines test expectation moved 2.0 → 2.5 — after the declined save the save-target is live under central path B with shared creation G, so the gapped entry''s creation-only close is itself the ruled-ambiguous configuration and now declines to session_end''s cap. Per PLN1 ruling #177 this is the final cycle.', '2026-07-19 03:08:39', '2026-07-19 03:13:28', 'shell', 'd7aabe7af9fd493b9252f94c0891142e');
