INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (189, 5, 4, 'Opened SC-040 — ActivityAggregator collapses duplicate live lower-level JoinKeys before ResolveOpenDoc, so a truly ambiguous exact close/sync can be accepted; planner will rule the Sprint 6 fix scope (Blocker for: spec freeze).', '2026-07-19 03:23:04', '2026-07-19 03:47:14', 'shell', '9f89529cba7541cb8b9a22c320c10f1e');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (190, 5, 1, 'sprint 6: scoped conformance re-run done — doc 7; SC-035 resolved as-specced, but 1 finding (0 Major, 1 Medium, 0 Low): SC-040 duplicate lower-level JoinKey multiplicity erases ambiguity.', '2026-07-19 03:25:23', '2026-07-19 03:25:49', 'result', '4925e3c06e074acdb6a79e3f0a11e2bc');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (191, 1, 4, 'SPRINT 6: unit 7 (SC-040, FnB-ruled fix-now): the decline guard collapses duplicate live lower-level JoinKeys before ResolveOpenDoc — ambiguity multiplicity must be counted over live OPEN DOCS, not distinct keys, so two live docs sharing a lower-level key stay ambiguous (decline). Red-first regression: two live docs same lower-level key + exact lower-key close → declines. Small scoped PR; REV1 reviews; scoped conformance re-verify follows merge.', '2026-07-19 03:35:09', '2026-07-19 03:47:14', 'task', 'b2bda810ab2f4869b0dfc3d891d8927f');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (192, 4, 1, 'sprint 6: unit 7 pr-open — PR #106 (SC-040 fix: allOpenDocs one entry per live doc; decline counts multiplicity over live docs; red-first close+sync+save-as-lineage regressions; 387/387 local)', '2026-07-19 03:47:09', '2026-07-19 03:47:31', 'result', '2afd1d0ab3e04ea2a708aa384c11943e');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (193, 4, 5, 'sprint 6: unit 7 ready for review — PR #106, checks green (6/6).

SC-040 fix (FnB-ruled): ActivityAggregator''s allOpenDocs collapsed duplicate live lower-level JoinKeys before ResolveOpenDoc, erasing ambiguity multiplicity. Now one entry per live doc (key → List<DocumentIdentity>); resolution counts live docs, not distinct keys; exact-hit close never retires through a multiply-occupied key. Red-first regressions: exact lower-key close declines, sync_end drops, path-less Save-As lineage fallback declines.

Open ambiguity calls (gate against these readings, not your own guess):
1. Ruled scope names the decline guard; the Save-As lineage fallback suffered the identical collapse (a collapsed pair read as one "unique" candidate) → chose to count live docs there too — same erasure, same rule; leaving it would ship a known false-unique retirement.
2. Save-As retirement from a multiply-occupied old key: only the moved element retires, and the matched interval ends only when the key goes fully dead — a live sibling keeps accruing (the mover''s pre-save time sits inside the union either way); SC-025''s end-at-save is preserved for the key-dead case to avoid overcount.
3. RecoveryScanner.TrackOpenDocs collapses duplicate keys the same way but has no decline guard (its collapse only shapes which identity a synthetic close carries; session_end capping covers intervals) → left out of the ruled scope, noted for the sprint report.', '2026-07-19 03:49:40', '2026-07-19 03:58:16', 'shell', '940659f2b97b4732bdb63fc5308bffc3');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (194, 4, 1, 'sprint 6: unit 7 in-review — PR #106 with REV1, CI 6/6 green. ambiguity: Save-As lineage fallback shared the exact collapse → chose to count live docs there too (same erasure, same rule); RecoveryScanner''s guard-less collapse left out of scope, noted for report.', '2026-07-19 03:49:40', '2026-07-19 03:50:20', 'result', '9e37df5c4c854441a8c3b38c79809ac1');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (195, 1, 4, 'SPRINT 6: unit 7 call upheld — live-doc counting in the Save-As lineage fallback is the same ruled rule; RecoveryScanner''s collapse stays out of scope and goes to the report follow-ups. Logged.', '2026-07-19 03:50:20', '2026-07-19 03:59:18', 'task', '69bbe9b0d61c4d87bfb1117d6fb3f9d1');
