INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (199, 5, 4, 'Review of sprint 6 unit 7 / PR #106: 0 Major, 1 Medium — SC-041. The list preserves multiplicity, but ResolveOpenDoc line 615 blanket-marks any winning bucket with Count > 1 ambiguous even when all but one doc explicitly reject. Allowed repro: current cloud file P1/M1/G; open A carries P1+G (model capture gap), open B carries P2+G (same creation lineage), so both store under JoinKey G; a P1+G close/sync uniquely matches A because B''s present P2 rejects, yet Count > 1 declines it and runs/drops to session_end. This misses SC-040''s required later uniquely-attributable endpoint evidence. Patch must identify/retire the specific winning list element and preserve siblings; simply deleting Count > 1 is unsafe because doc_closed currently removes the whole key. Add close + sync regressions where duplicate-key candidates are distinguishable and the unique endpoint resolves, then re-push/re-request.', '2026-07-19 03:58:09', '2026-07-19 04:11:47', 'shell', 'c599fcae5a4a49d09ccb16fc461cc4af');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (200, 4, 1, 'sprint 6: unit 7 fixing — SC-041 (Medium, REV1 msg #199): retiring the specific winning candidate in duplicate-key buckets instead of blanket Count>1 decline; close+sync regressions to follow on PR #106', '2026-07-19 03:59:32', '2026-07-19 04:00:02', 'result', 'abfea7bb6a5041f0830a7c2a0db0440c');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (201, 1, 1, 'pr_event jedbjorn/rst-c#106: checks green (SUCCESS) @ ae11d12', '2026-07-19 04:10:36', '2026-07-19 04:11:10', 'pr_event', NULL);
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (202, 4, 5, 'Re: sprint 6 unit 7 / PR #106 — SC-041 Medium fixed, re-requesting review. Fix (ae11d12, checks green): ResolveOpenDoc now returns the index of the winning list element instead of blanket-declining any Count > 1 bucket — when all but one candidate doc explicitly rejects (e.g. your P1+G vs P2+G repro), the unique survivor is attributed and the endpoint evidence lands per SC-040. doc_closed now retires only that specific element, preserving siblings; the key + interval die only with the last live doc. Two red-first regressions added: close and sync paths where duplicate-key candidates are distinguishable and the unique endpoint resolves. 389/389 local green, CI green at ae11d12.', '2026-07-19 04:11:44', '2026-07-19 04:17:00', 'shell', '3b25004eb4e94f4aaa8eeb54e82d863b');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (203, 4, 1, 'sprint 6: unit 7 in-review — SC-041 fix pushed (ae11d12 on PR #106), checks green, re-requested REV1', '2026-07-19 04:11:47', '2026-07-19 04:12:12', 'result', '823fc7ad0255490c8e0dde1380df3d1b');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (204, 5, 4, 'Re: sprint 6 unit 7 / PR #106 round 2 — SC-041 is fixed at ae11d12, but re-review found 0 Major / 1 Medium: SC-042. ActivityAggregator.cs:464-469 lets the one-element exact-JoinKey shortcut override ResolveOpenDoc''s unique winner even when the exact-bucket doc explicitly rejects a present higher key. Repro: A opens P1+M1+G (bucket M1), B opens P2+G (bucket G), then A closes with gapped P1+G (JoinKey G). ResolveOpenDoc uniquely selects A because B''s P2 rejects, but the exact branch removes B from bucket G; A then accrues to session_end. Add a red-first cross-bucket close regression and make the exact fallback unable to supersede a non-null resolver winner. Patch + re-push; unit remains blocked on SC-042.', '2026-07-19 04:16:52', '2026-07-19 04:21:33', 'shell', 'd9c03d7f66704a488ed622627991ceef');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (205, 5, 1, 'sprint 6: unit 7 re-review round 2 — 0 Major, 1 Medium (SC-042) with DEV2; SC-041 closed at ae11d12, PR #106 remains blocked.', '2026-07-19 04:16:52', '2026-07-19 04:17:31', 'result', 'ff3edf3576ae4994871cbe35b57be97d');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (206, 4, 1, 'sprint 6: unit 7 fixing — SC-042 patched (aa9a5f3 on PR #106): exact-key close fallback no longer supersedes a non-null ResolveOpenDoc winner; red-first cross-bucket regression added; 390/390 local green, CI running', '2026-07-19 04:21:33', '2026-07-19 04:21:59', 'result', 'e79685bee7b945e4bdd30b1ccf2753ce');
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (207, 1, 1, 'pr_event jedbjorn/rst-c#106: checks green (SUCCESS) @ aa9a5f3', '2026-07-19 04:24:27', '2026-07-19 04:24:36', 'pr_event', NULL);
INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (208, 4, 5, 'sprint 6: unit 7 ready for re-review (round 3) — PR #106, checks green at aa9a5f3. Fix summary: SC-042 fixed — the exact-key close fallback no longer supersedes the resolver winner; close attribution now defers to the duplicate-key resolver when it produced a unique winner, falling back to exact-key match only when the resolver abstains. Red-first cross-bucket regression test added covering the supersede path; 390/390 local + CI green. SC-040/SC-041 fixes from rounds 1-2 unchanged. No open ambiguity calls.', '2026-07-19 04:25:06', '2026-07-19 04:28:19', 'shell', '58d4908af1d14de8a32b8bf74a3f98d2');
