INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (217, 1, 4, 'SPRINT 6: unit 8 (SC-043, conformance doc 7 — completes SC-041 under the FnB''s clean-before-freeze mandate): current-file interval occupancy must be tracked per matched live element (matched ref-count), independent of the all-doc resolver bucket — a uniquely attributed close ends the current-file interval when the LAST MATCHING element closes, even if a rejecting sibling remains; keep SC-040''s ambiguous-decline behavior. Update the existing regression at ActivityAggregatorTests (A opens 09:00 P1+G, B 09:30 P2+G, A closes 10:00, B closes 11:00) to assert A=1.0h and B=1.5h, red-first. Small scoped PR; REV1 reviews; final scoped conformance re-verify follows.', '2026-07-19 04:37:03', '2026-07-19 04:37:32', 'task', 'f7bf5894ea364eb98f23199e8cb000f4');
